import { useState } from 'react';
import { Screen, Card, Grid, Stack, Row, Button, Badge, Alert, KeyBar } from '@nexti/ds';

type Scenario = 'exito' | 'rechazado';

const SAMPLES: Record<Scenario, { RORDEN: string; RCOMIS: string; RMOVIM: string; RMENS: string }> = {
  exito: {
    RORDEN: '0004821',
    RCOMIS: '    12.50',
    RMOVIM: '    784513',
    RMENS: 'PAGO APLICADO CORRECTAMENTE',
  },
  rechazado: {
    RORDEN: '0004822',
    RCOMIS: '     0.00',
    RMOVIM: '         0',
    RMENS: 'PAGO RECHAZADO - SALDO INSUFICIENTE',
  },
};

function OutputValue({ name, label, children }: { name: string; label: string; children: React.ReactNode }) {
  return (
    <div data-field={name} style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
      <span style={{ fontSize: 13, color: '#555' }}>{label}</span>
      <output
        aria-label={label}
        style={{ fontSize: 18, fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}
      >
        {children}
      </output>
    </div>
  );
}

export default function PagoResultado({ navigate }: { navigate: (to: string) => void }) {
  const [scenario, setScenario] = useState<Scenario>('exito');
  const data = SAMPLES[scenario];
  const ok = scenario === 'exito';

  const nuevoPago = () => navigate('SCR-PAGOORD');
  const menu = () => navigate('SCR-PAGOMEN');

  return (
    <Screen
      title="Resultado del pago"
      code="PAGORES"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Nuevo pago', onPress: nuevoPago, primary: true },
            { key: 'PF3', label: 'Menú', onPress: menu },
          ]}
        />
      }
    >
      <Stack>
        <Alert tone={ok ? 'success' : 'error'}>
          {ok
            ? 'El pago se registró correctamente. Revise el detalle a continuación.'
            : 'El pago no pudo aplicarse. Revise el resultado y vuelva a intentarlo con un nuevo pago.'}
        </Alert>

        <Card title="Detalle del resultado">
          <Stack>
            <Grid columns={2}>
              <OutputValue name="RORDEN" label="Orden">
                {data.RORDEN}
              </OutputValue>
              <OutputValue name="RMOVIM" label="Movimiento">
                {data.RMOVIM.trim()}
              </OutputValue>
              <OutputValue name="RCOMIS" label="Comisión">
                {data.RCOMIS.trim()}
              </OutputValue>
              <div data-field="RMENS" style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
                <span style={{ fontSize: 13, color: '#555' }}>Resultado</span>
                <Row>
                  <Badge>{ok ? 'OK' : 'Error'}</Badge>
                  <output aria-label="Resultado" style={{ fontSize: 18, fontWeight: 700 }}>
                    {data.RMENS}
                  </output>
                </Row>
              </div>
            </Grid>
          </Stack>
        </Card>

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={nuevoPago}>
            Nuevo pago
          </Button>
          <Button variant="secondary" shortcut="PF3" onClick={menu}>
            Menú
          </Button>
        </Row>

        <Card title="Vista previa del prototipo">
          <Row>
            <Button
              variant={ok ? 'primary' : 'ghost'}
              onClick={() => setScenario('exito')}
            >
              Ver pago aplicado
            </Button>
            <Button
              variant={!ok ? 'danger' : 'ghost'}
              onClick={() => setScenario('rechazado')}
            >
              Ver pago rechazado
            </Button>
          </Row>
        </Card>
      </Stack>
    </Screen>
  );
}
```
